@@ -0,0 +1,87 @@
+import type { SessionEvent } from '../types.ts';
+
+// Slop: shortcuts that make work look done. They are flags for the model and the user, never refusals.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+
+export type SlopRule = 'test-deleted' | 'test-weakened' | 'test-skipped' | 'suppression' | 'swallowed-error' | 'type-escape' | 'stub';
+
+export type Finding = { rule: SlopRule; path: string; line?: string };
+
+const TEST_FILE = /(\.test\.|\.spec\.|_test\.(go|py)$|(^|\/)test_[^/]*\.py$|(^|\/)tests?\/)/;
+const PROSE_FILE = /\.(md|mdx|txt|rst|adoc)$/i;
+const ASSERTION = /\bexpect\(|\bassert|\bt\.(Error|Errorf|Fatal|Fatalf)\(/;
+
+// Rules that look at each added line. A test-only rule applies to test files alone.
+const LINE_RULES: { rule: SlopRule; re: RegExp; testOnly?: boolean }[] = [
+  { rule: 'test-skipped', re: /\b(it|test|describe)\.skip\(|\bx(it|test|describe)\(|\bt\.Skip(f|Now)?\(|@pytest\.mark\.skip|pytest\.skip\(|@unittest\.skip|#\[ignore\]/, testOnly: true },
+  { rule: 'suppression', re: /@ts-(ignore|nocheck)|eslint-disable|#\s*type:\s*ignore|#\s*noqa\b|pylint:\s*disable|\/\/\s*nolint|#\[allow\(|@SuppressWarnings/ },
+  { rule: 'swallowed-error', re: /\bcatch\s*(\([^)]*\))?\s*\{\s*\}|^\s*except\b[^:]*:\s*pass\s*$/ },
+  { rule: 'type-escape', re: /\bas any\b/ },
+  { rule: 'stub', re: /throw new Error\(\s*['"`]not implemented|NotImplementedError|\btodo!\(|\bunimplemented!\(/i },
+];
+
+export function findSlop(changes: FileChange[]): Finding[] {
+  const out: Finding[] = [];
+  for (const c of changes) {
+    const test = TEST_FILE.test(c.path);
+    if (c.deleted) {
+      if (test) out.push({ rule: 'test-deleted', path: c.path });
+      continue;
+    }
+    if (PROSE_FILE.test(c.path)) continue;
+    const count = (lines: string[]) => lines.filter((l) => ASSERTION.test(l)).length;
+    if (test && count(c.removed) > count(c.added)) out.push({ rule: 'test-weakened', path: c.path });
+    for (const line of c.added)
+      for (const r of LINE_RULES)
+        if ((test || !r.testOnly) && r.re.test(line)) out.push({ rule: r.rule, path: c.path, line: line.trim().slice(0, 100) });
+  }
+  return out;
+}
+
+// The flag as the evidence and the reminder name it: `suppression a.ts: // @ts-ignore`.
+export const flagText = (f: Finding) => `${f.rule} ${f.path}${f.line ? `: ${f.line}` : ''}`;
+
+// Reads a `git diff` patch (headers and hunks, with or without -U0). Only the +/- lines of hunks count.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  for (const line of patch.split('\n')) {
+    if (line.startsWith('diff --git ')) {
+      cur = { path: '', added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+      continue;
+    }
+    if (!cur) continue;
+    if (line.startsWith('@@')) inHunk = true;
+    else if (!inHunk) {
+      if (line === '+++ /dev/null') cur.deleted = true;
+      else if (line.startsWith('--- a/') || line.startsWith('+++ b/')) cur.path = line.slice(6);
+    } else if (line.startsWith('+')) cur.added.push(line.slice(1));
+    else if (line.startsWith('-')) cur.removed.push(line.slice(1));
+  }
+  return out.filter((c) => c.path);
+}
+
+// Without snapshots, a run's changes are what its completed edit and write calls wrote.
+export function changesFromCalls(events: SessionEvent[]): FileChange[] {
+  const done = new Set(events.flatMap((e) => (e.kind === 'tool_result' && e.status === 'completed' ? [e.callId] : [])));
+  const lines = (s: unknown) => (typeof s === 'string' ? s.split('\n') : []);
+  const out: FileChange[] = [];
+  for (const e of events) {
+    if (e.kind !== 'tool_intent' || !done.has(e.callId)) continue;
+    const path = String(e.input.path ?? '');
+    if (e.tool === 'write') out.push({ path, added: lines(e.input.content), removed: [], deleted: false });
+    else if (e.tool === 'edit') {
+      const edits = Array.isArray(e.input.edits) ? (e.input.edits as { old_text?: unknown; new_text?: unknown }[]) : [];
+      out.push({
+        path,
+        added: edits.flatMap((x) => lines(x.new_text)),
+        removed: edits.flatMap((x) => lines(x.old_text)),
+        deleted: false,
+      });
+    }
+  }
+  return out;
+}
