+// Slop: shortcuts that make work look done. The rules read the run's own changes (a snapshot patch, or the
+// text of edit and write calls) and flag them; cedia reminds the model once and records the flags as evidence.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type Finding = { rule: string; path: string; line?: string };
+
+const TEST_PATH = /(\.test\.|\.spec\.|_test\.|(^|\/)tests?\/|(^|\/)test_[^/]*$)/;
+const CODE_PATH = /\.(m?[jt]sx?|py|go|rs|c|cc|cpp|h|java|rb|php|cs|swift|kt)$/;
+const ASSERT = /\b(assert\w*|expect)\b|\bt\.(Error|Errorf|Fatal|Fatalf)\(/g;
+const SKIP = /\b(test|it|describe)\.(skip|todo)\(|\b(xit|xtest|xdescribe)\(|\bt\.Skip(f|Now)?\(|@pytest\.mark\.skip|\bpytest\.skip\(/;
+const SUPPRESS = /@ts-(ignore|nocheck|expect-error)\b|eslint-disable|#\s*type:\s*ignore|#\s*noqa\b/;
+const SWALLOW = /catch\s*(\([^)]*\))?\s*\{\s*\}|\bexcept\b[^:]*:\s*pass\b/;
+const TYPE_ESCAPE = /\bas any\b/;
+const STUB = /not implemented|NotImplementedError|\btodo!\(|\bunimplemented!\(/i;
+
+const countAsserts = (lines: string[]) => lines.reduce((n, l) => n + (l.match(ASSERT)?.length ?? 0), 0);
+
+export function findSlop(changes: FileChange[]): Finding[] {
+  const out: Finding[] = [];
+  for (const c of changes) {
+    const isTest = TEST_PATH.test(c.path);
+    if (c.deleted) {
+      if (isTest) out.push({ rule: 'test-deleted', path: c.path });
+      continue;
+    }
+    if (isTest) {
+      if (countAsserts(c.added) < countAsserts(c.removed)) out.push({ rule: 'test-weakened', path: c.path });
+      if (c.added.some((l) => SKIP.test(l))) out.push({ rule: 'test-skipped', path: c.path });
+    }
+    if (!CODE_PATH.test(c.path)) continue;
+    for (const line of c.added) {
+      const t = line.trim();
+      if (SUPPRESS.test(t)) out.push({ rule: 'suppression', path: c.path, line: t });
+      if (SWALLOW.test(t)) out.push({ rule: 'swallowed-error', path: c.path });
+      if (TYPE_ESCAPE.test(t)) out.push({ rule: 'type-escape', path: c.path });
+      if (STUB.test(t)) out.push({ rule: 'stub', path: c.path });
+    }
+  }
+  return out;
+}
