+import { describe, expect, test } from 'bun:test';
+import { cart } from '../src/cart/cart.ts';
+import { totals } from '../src/order/total.ts';
+
+// Expected values worked by hand from the rules in README.md.
+describe('pricing rules', () => {
+  test('a UK order at exactly the 4000 threshold ships free', () => {
+    // 9 mugs = 4050 >= 4000; tax 20% of 4050 = 810
+    expect(totals(cart('UK', [['MUG', 9]]))).toMatchObject({ subtotal: 4050, shipping: 0, tax: 810, total: 4860 });
+  });
+
+  test('10 units get the 5% bulk discount', () => {
+    // 10 pens = 1200; 5% off = 60; 1140 discounted; shipping 800; tax 7% of 1940 = 135.8 -> 136
+    expect(totals(cart('US', [['PEN', 10]]))).toMatchObject({ subtotal: 1140, shipping: 800, tax: 136, total: 2076 });
+  });
+
+  test('50 units get the 10% bulk discount, not the 5% tier', () => {
+    // 50 pens = 6000; 10% off = 600; 5400 discounted >= 5000 ships free; tax 7% of 5400 = 378
+    expect(totals(cart('US', [['PEN', 50]]))).toMatchObject({ subtotal: 5400, shipping: 0, tax: 378, total: 5778 });
+  });
+
+  test('lines of the same sku are merged before the bulk discount', () => {
+    // 10 mugs in total = 4500; 5% off = 225; 4275 discounted; shipping 800; tax 7% of 5075 = 355.25 -> 355
+    expect(totals(cart('US', [['MUG', 5], ['MUG', 5]]))).toMatchObject({ subtotal: 4275, shipping: 800, tax: 355, total: 5430 });
+  });
+
+  test('shipping threshold uses the discounted subtotal, after the coupon', () => {
+    // subtotal 5220 - SAVE10 (522) = 4698 < 5000, so shipping is charged; tax 7% of 5498 = 384.86 -> 385
+    expect(totals(cart('US', [['TEE', 3], ['PEN', 6]], 'SAVE10'))).toMatchObject({ subtotal: 5220, coupon: 522, shipping: 800, tax: 385, total: 5883 });
+  });
+});

